import 'package:flutter_test/flutter_test.dart';
import 'package:accounting_software/app/features/catalog/materials/presentation/widgets/material_field_validators.dart';
void main(){group('MaterialFieldValidators',(){test('requires a name and code',(){expect(MaterialFieldValidators.name(' '),isNotNull);expect(MaterialFieldValidators.code(null),isNotNull);});test('enforces schema lengths',(){expect(MaterialFieldValidators.name('x'*101),isNotNull);expect(MaterialFieldValidators.code('x'*51),isNotNull);});test('accepts valid values',(){expect(MaterialFieldValidators.name('Cotton'),isNull);expect(MaterialFieldValidators.code('COT'),isNull);});});}
